// The Strongroom vault: tiers, what each costs, the layout used. Pure, loads in Node.
// Rooms: rooms_data.js (generated by map/structures/export_vaults.py from vault_rooms.py).

export const VAULT_KEY = "siege:vault_key";
export const TIERS = ["wood", "iron", "diamond", "netherite", "choirsteel"];
export const TIER_NAME = { wood: "Wooden Strongroom", iron: "Iron Strongroom", diamond: "Diamond Strongroom",
  netherite: "Netherite Strongroom", choirsteel: "Choirsteel Strongroom" };

// Which of the three room layouts the game builds (treasury | hall | crypt). Mateo picks per tier; until then treasury.
export const LAYOUT = { wood: "treasury", iron: "treasury", diamond: "treasury", netherite: "treasury", choirsteel: "treasury" };

const isPlanks = (id) => id.endsWith("_planks");
const is = (want) => (id) => id === want;

// Cost to add the vault (wood) and, later, to reinforce it to each tier: [label, amount, match(itemId)].
// Placeholder numbers until Mateo sets them.
export const COSTS = {
  wood: [["planks (any wood)", 64, isPlanks], ["cobbled deepslate", 32, is("minecraft:cobbled_deepslate")]],
  iron: [["iron ingots", 32, is("minecraft:iron_ingot")]],
  diamond: [["diamonds", 16, is("minecraft:diamond")]],
  netherite: [["netherite ingots", 4, is("minecraft:netherite_ingot")]],
  choirsteel: [["Choirsteel ingots", 2, is("siege:choirsteel_ingot")]],
};

// Turn a local design cell into world coordinates (same frame as townhall/halls.js toWorld)
export function worldOf(v, x, y, z) {
  const F = { x: v.fx, z: v.fz }, R = { x: -v.fz, z: v.fx };
  return { x: v.x + x * R.x + z * F.x, y: v.y - 1 + y, z: v.z + x * R.z + z * F.z };
}

// The ground box (x0..x1, z0..z1) a room covers in the world
export function groundBox(v, box) {
  const a = worldOf(v, box.x0, 0, box.z0), b = worldOf(v, box.x1, 0, box.z1);
  return { x0: Math.min(a.x, b.x), x1: Math.max(a.x, b.x), z0: Math.min(a.z, b.z), z1: Math.max(a.z, b.z) };
}

// Click the Vault Lock holding one of these to reinforce the vault to that tier (one tier at a time)
export const UPGRADE_ITEM = { iron: "minecraft:iron_ingot", diamond: "minecraft:diamond", netherite: "minecraft:netherite_ingot", choirsteel: "siege:choirsteel_ingot" };
export const nextTier = (tier) => TIERS[TIERS.indexOf(tier) + 1];
